func test_duckdb_TestDuckDB_test_timestamp_from_parts(self *Case, a Args) Value {
	var source, target, dtype, dialect, sql, expression Value
	_ = []Value{source, target, dtype, dialect, sql, expression}
	for _, item_ := range Iter(NewTuple(NewTuple("SELECT TIMESTAMP_FROM_PARTS(2019, 1, 10, 2, 3, 4, 0, 'America/Los_Angeles')", "SELECT MAKE_TIMESTAMP(2019, 1, 10, 2, 3, 4 + (0 / 1000000000.0)) AT TIME ZONE 'America/Los_Angeles'", A(A(G("sqlglot.exp"), "DType"), "TIMESTAMPTZ")), NewTuple("SELECT TIMESTAMP_FROM_PARTS(2019, 7, 10, 2, 3, 4, 123456000, 'America/Los_Angeles')", "SELECT MAKE_TIMESTAMP(2019, 7, 10, 2, 3, 4 + (123456000 / 1000000000.0)) AT TIME ZONE 'America/Los_Angeles'", A(A(G("sqlglot.exp"), "DType"), "TIMESTAMPTZ")), NewTuple("SELECT TIMESTAMP_FROM_PARTS(2019, 1, 10, 2, 3, 4, ns, tz) FROM (VALUES (123456000, 'America/Los_Angeles'), (NULL, 'UTC'), (0, NULL)) AS t(ns, tz)", "SELECT MAKE_TIMESTAMP(2019, 1, 10, 2, 3, 4 + (ns / 1000000000.0)) AT TIME ZONE tz FROM (VALUES (123456000, 'America/Los_Angeles'), (NULL, 'UTC'), (0, NULL)) AS t(ns, tz)", A(A(G("sqlglot.exp"), "DType"), "TIMESTAMPTZ")), NewTuple("SELECT TIMESTAMP_FROM_PARTS(2019, 1, 10, 2, 3, 4, 123456000)", "SELECT MAKE_TIMESTAMP(2019, 1, 10, 2, 3, 4 + (123456000 / 1000000000.0))", A(A(G("sqlglot.exp"), "DType"), "TIMESTAMP")))) {
		Unpack(item_, &source, &target, &dtype)
		self.SubTest(func() {
			self.Do(2934, func() {
				self.ValidateAll(target, Kw("read", NewDict("snowflake", source)), Kw("write", NewDict("duckdb", target)))
			})
			for _, item_ := range Iter(NewTuple(NewTuple("snowflake", source), NewTuple("duckdb", target))) {
				Unpack(item_, &dialect, &sql)
				self.Do(2936, func() {
					expression = Call(G("sqlglot.optimizer.annotate_types.annotate_types"), Call(G("sqlglot.parse_one"), sql, Kw("read", dialect)), Kw("dialect", dialect))
				})
				self.Do(2937, func() {
					self.AssertEqual(A(Item(A(expression, "selects"), 0), "type"), M(A(G("sqlglot.exp"), "DataType"), "build", dtype))
				})
			}
		}, Kw("source", source))
	}
	return nil
}

